import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Ynmo Flow, phase 1: menu, create tickets (all types and the parent rules), list, filters, My work, ticket window, status change, history, delete, reload. Fake test database only."""
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    nb=A.locator('#nav button[data-p="flow"]')
    ok('F1 the menu has a Ynmo Flow button with an icon', nb.count()==1 and nb.get_attribute('aria-label')=='Ynmo Flow' and nb.locator('svg').count()==1)
    nb.click(); A.wait_for_timeout(500)
    ok('F2 it opens the Flow page with the title', A.locator('.flowproj b').inner_text()=='Ynmo Flow' and A.locator('#ptitle').inner_text()=='Ynmo Flow')
    items=A.locator('.flowitem'); labels=[items.nth(i).locator('span').first.inner_text().strip() for i in range(items.count())]
    ok('F2a Jira-style sidebar with all views and one board per product', labels==['For you','My work','Summary','Performance','Epics','Backlog','Sprints','Active sprint','All products','Tifli','AI','Daycare','Plan','SCHS','Warif','All issues','Details','Issue types','Workflow'] and A.locator('.flowitem svg').count()==19 and A.locator('.flowgt').count()==4)
    ok('F2b it lands on Summary, which is current in the sidebar, with zero counts', A.locator('.flowitem[aria-current="page"] span').first.inner_text().strip()=='Summary' and A.locator('.fstat[data-stat="Total tickets"] b').inner_text()=='0')
    A.click('.flowitem[data-view="issues"]'); A.wait_for_timeout(300)
    ok('F3 empty state invites the first ticket and Create is enabled', 'No tickets yet' in A.locator('#flowbody').inner_text() and A.locator('#flowcreate').is_enabled())
    ok('F4 the address shows #/flow and the button is current', A.evaluate("location.hash")=='#/flow/issues' and nb.get_attribute('aria-current')=='page')
    def create(typ,title,asg='',par='',ep='',desc=''):
        A.click('#flowcreate'); A.wait_for_timeout(200)
        A.select_option('#fc-type',typ)
        if par: A.select_option('#fc-par',label=par)
        if ep: A.select_option('#fc-ep',label=ep)
        A.fill('#fc-title',title)
        if desc: A.fill('#fc-desc',desc)
        if asg: A.select_option('#fc-as',asg)
        A.click('#fc-ok'); A.wait_for_timeout(300)
    create('epic','Payments')
    ok('F5 the first ticket is YNMO-1 and shows in the list', A.locator('.flowrow').count()==1 and A.locator('.flowrow .fkey').first.inner_text()=='YNMO-1')
    create('story','Pay by card',asg='Admin',ep='YNMO-1 Payments',desc='Card form and receipt')
    create('bug','Totals are wrong',asg='Admin')
    create('hotfix','Receipt typo')
    ok('F6 four tickets, newest first', A.locator('.flowrow').count()==4 and A.locator('.flowrow .fkey').first.inner_text()=='YNMO-4')
    A.click('#flowcreate'); A.wait_for_timeout(200); A.select_option('#fc-type','subtask'); A.fill('#fc-title','Form'); A.click('#fc-ok'); A.wait_for_timeout(200)
    ok('F7 a sub-task without a parent is refused with a message and the window stays', A.locator('#fc-err').is_visible() and 'parent' in A.locator('#fc-err').inner_text() and A.locator('#fc-title').count()==1)
    A.select_option('#fc-type','story'); A.wait_for_timeout(100)
    ok('F8 parent field is hidden for a story and the epic field is shown', not A.locator('#fc-par').is_visible() and A.locator('#fc-ep').is_visible())
    A.select_option('#fc-type','epic'); A.wait_for_timeout(100)
    ok('F9 an epic has neither parent nor epic', not A.locator('#fc-par').is_visible() and not A.locator('#fc-ep').is_visible())
    A.click('button:text-is("Cancel")'); A.wait_for_timeout(200)
    # open the story and add sub-tasks
    A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300)
    ok('F10 the ticket window shows key, fields and the description', A.locator('#fi-title').input_value()=='Pay by card' and A.locator('#fi-desc').input_value()=='Card form and receipt' and A.locator('#fi-as').input_value()=='Admin')
    ok('F11 a story offers both Add sub-task and Add sub-bug', A.locator('[data-add="subtask"]').count()==1 and A.locator('[data-add="subbug"]').count()==1)
    A.click('[data-add="subtask"]'); A.wait_for_timeout(250)
    ok('F12 the sub-ticket window is preset to Sub-task under the story', A.locator('#fc-type').input_value()=='subtask' and A.locator('#fc-par').input_value()!='')
    A.fill('#fc-title','Card form'); A.select_option('#fc-as','Admin'); A.click('#fc-ok'); A.wait_for_timeout(300)
    A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300)
    A.click('[data-add="subbug"]'); A.wait_for_timeout(250); A.fill('#fc-title','Card form crashes'); A.click('#fc-ok'); A.wait_for_timeout(300)
    A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300)
    ok('F13 the story lists its two sub-tickets', A.locator('.flowkid').count()==2)
    # change status and save
    A.select_option('#fi-st','progress'); A.click('#fi-save'); A.wait_for_timeout(300)
    ok('F14 the status change shows in the list', A.locator('.flowrow',has_text='Pay by card').locator('td.k-st').inner_text()=='In progress')
    A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300)
    ok('F15 history lists the creation and the status change', 'Open → In progress' in A.locator('.flowhist').inner_text() and 'created YNMO-2' in A.locator('.flowhist').inner_text())
    A.click('button:text-is("Close")'); A.wait_for_timeout(200)
    # filters
    A.fill('#flowq','typo'); A.wait_for_timeout(200)
    ok('F16 text search narrows the list', A.locator('.flowrow').count()==1 and 'Receipt typo' in A.locator('.flowrow').inner_text())
    A.fill('#flowq',''); A.select_option('#flowtype','bug'); A.wait_for_timeout(200)
    ok('F17 type filter', A.locator('.flowrow').count()==1 and 'Totals' in A.locator('.flowrow').inner_text())
    A.select_option('#flowtype',''); A.select_option('#flowas','@none'); A.wait_for_timeout(200)
    ok('F18 unassigned filter', A.locator('.flowrow').count()==3)
    A.select_option('#flowas',''); A.select_option('#flowep',index=1); A.wait_for_timeout(200)
    ok('F19 epic filter shows the tickets of the epic', A.locator('.flowrow').count()==1 and 'Pay by card' in A.locator('.flowrow').inner_text())
    A.select_option('#flowep',''); A.click('.flowchips [data-st="progress"]'); A.wait_for_timeout(300)
    ok('F20 clicking a status chip filters by it and clicking again clears it', A.locator('.flowrow').count()==1 and A.locator('.flowchips [data-st="progress"]').get_attribute('aria-pressed')=='true')
    A.click('.flowchips [data-st="progress"]'); A.wait_for_timeout(300)
    ok('F21 filters cleared', A.locator('.flowrow').count()==6)
    # my work
    A.click('.flowitem[data-view="mine"]'); A.wait_for_timeout(300)
    ok('F22 My work: assigned ticket, sub-task and bug sit in their own sections', A.locator('#mine-tickets .flowrow').count()==1 and A.locator('#mine-subs .flowrow').count()==1 and A.locator('#mine-bugs .flowrow').count()==1)
    # done hides, all shows
    A.locator('#mine-bugs .flowrow').click(); A.wait_for_timeout(300); A.select_option('#fi-st','done'); A.click('#fi-save'); A.wait_for_timeout(300)
    ok('F23 a Done ticket leaves My work', A.locator('#mine-bugs .flowrow').count()==0)
    A.check('#flowall'); A.wait_for_timeout(300)
    ok('F24 Include Deployed and Done brings it back', A.locator('#mine-bugs .flowrow').count()==1)
    # summary, epics, board, soon pages, settings
    A.click('.flowitem[data-view="summary"]'); A.wait_for_timeout(300)
    ok('F24a Summary shows the totals, status bars and recent activity', A.locator('.fstat[data-stat="Total tickets"] b').inner_text()=='6' and A.locator('.fbrow').count()>=7 and 'YNMO-' in A.locator('.frecent').inner_text() and A.locator('.fstat[data-stat="In progress"] b').inner_text()=='1')
    A.locator('.frecent .flink').first.click(); A.wait_for_timeout(300)
    ok('F24b a key in Recent activity opens that ticket', A.locator('#fi-title').count()==1); A.click('button:text-is("Close")'); A.wait_for_timeout(200)
    A.click('.flowitem[data-view="epics"]'); A.wait_for_timeout(300)
    ok('F24c Epics lists the epic with its progress', A.locator('.fepic').count()==1 and '0 of 1 tickets closed' in A.locator('.fepic').inner_text())
    A.click('.flowitem[data-view="board"]'); A.wait_for_timeout(300)
    ok('F24d Board has a column per status and puts tickets in their column', A.locator('.fcol').count()==7 and A.locator('.fcol[data-st="progress"] .fcard').count()==1 and A.locator('.fcol[data-st="done"] .fcard').count()==1 and A.locator('.fcol[data-st="open"] .fcard').count()>=2)
    A.locator('.fcol[data-st="progress"] .fcard').drag_to(A.locator('.fcol[data-st="rfqa"]')); A.wait_for_timeout(400)
    ok('F24e dragging a card to another column moves its status', A.locator('.fcol[data-st="rfqa"] .fcard').count()==1 and A.locator('.fcol[data-st="progress"] .fcard').count()==0)
    A.locator('.fcol[data-st="rfqa"] .fcard').click(); A.wait_for_timeout(300)
    ok('F24f the move is in the ticket history', 'In progress → RFQA' in A.locator('.flowhist').inner_text()); A.click('button:text-is("Close")'); A.wait_for_timeout(200)
    A.click('#boardmine'); A.wait_for_timeout(200)
    ok('F24g Only my tickets keeps the cards assigned to me', A.locator('.fcard').count()==3 and A.locator('#boardmine').get_attribute('aria-pressed')=='true')
    A.click('.flowitem[data-view="backlog"]'); A.wait_for_timeout(250)
    ok('F24h Backlog is a real page with a Backlog list and a Create sprint button', A.locator('.fsprint[data-sp=""]').count()==1 and A.locator('#sp-create').count()==1 and A.locator('.flowh1').inner_text()=='Backlog')
    A.click('.flowitem[data-view="set-types"]'); A.wait_for_timeout(250)
    ok('F24i Issue types lists the eight types with the parent rules', A.locator('.flowbody tbody tr, #flowbody tbody tr').count()==8 and 'Story' in A.locator('#flowbody').inner_text())
    A.click('.flowitem[data-view="set-workflow"]'); A.wait_for_timeout(250)
    ok('F24j Workflow lists the seven statuses in order', A.locator('.fwft tbody tr').count()==7 and A.locator('.fwft tbody tr').nth(4).locator('.wf-name').input_value()=='Ready for deployment')
    A.click('.flowitem[data-view="set-details"]'); A.wait_for_timeout(250)
    ok('F24k Details shows the key', 'YNMO' in A.locator('#flowbody').inner_text())
    A.go_back(); A.wait_for_timeout(300)
    ok('F24l the browser Back button returns to the previous view', A.evaluate("location.hash")=='#/flow/set-workflow' and A.locator('.flowitem[aria-current="page"] span').first.inner_text().strip()=='Workflow')
    A.click('.flowitem[data-view="issues"]'); A.wait_for_timeout(300)
    # reload persists
    A.reload(); A.wait_for_timeout(3500)
    ok('F25 a reload stays on Flow and the tickets are still there (the Done one is hidden by default)', A.locator('#pg-flow:not([hidden])').count()==1 and A.evaluate('location.hash')=='#/flow/issues' and A.locator('.flowrow').count()==5)
    # delete
    A.locator('.flowrow',has_text='Receipt typo').click(); A.wait_for_timeout(300); A.click('#fi-del'); A.wait_for_timeout(200); A.click('button:text-is("Delete")'); A.wait_for_timeout(400)
    ok('F26 delete removes the ticket after a confirm', A.locator('.flowrow').count()==4 and 'Receipt typo' not in A.locator('#flowbody').inner_text())
    # layout (design review)
    A.click('#flowcreate'); A.wait_for_timeout(250)
    bt=A.locator('#fc-title').bounding_box(); bl=A.locator('label:has(#fc-title) > span').bounding_box(); bs=A.locator('#fc-as').bounding_box(); bx=A.locator('.flowcreate').bounding_box()
    ok('F28 create form: the label sits above the field, the title is full width and as tall as the selects', bl['y']+bl['height']<=bt['y']+1 and bt['width']>bx['width']*0.8 and abs(bt['height']-bs['height'])<=6)
    A.click('button:text-is("Cancel")'); A.wait_for_timeout(200)
    A.click('.flowitem[data-view="mine"]'); A.wait_for_timeout(300); A.check('#flowall'); A.wait_for_timeout(300)
    xs=A.evaluate("[...document.querySelectorAll('#flowbody .flowtbl')].map(t=>[...t.querySelectorAll('th')].map(h=>Math.round(h.getBoundingClientRect().left)).join())")
    ok('F29 My work: every list has the same columns in the same places', len(xs)>=4 and len(set(xs))==1)
    A.click('.flowrow >> nth=0'); A.wait_for_timeout(300)
    ok('F30 ticket window is two columns: fields on the side, nothing sticks out', A.locator('.fsidec #fi-st').count()==1 and A.locator('.fmainc #fi-title').count()==1 and A.evaluate("document.querySelector('.flowdlg').scrollWidth<=document.querySelector('.flowdlg').clientWidth+1"))
    A.click('button:text-is("Close")'); A.wait_for_timeout(200)
    A.set_viewport_size({'width':390,'height':844}); A.wait_for_timeout(300)
    ok('F31 on a phone the page does not scroll sideways and the sidebar becomes a one-row strip', A.evaluate("document.documentElement.scrollWidth<=innerWidth+1") and A.evaluate("document.querySelector('.flowside').getBoundingClientRect().height<70"))
    A.set_viewport_size({'width':1400,'height':900}); A.wait_for_timeout(200)
    ok('F27 no script errors', not errs)
    if errs: print(errs)
    b.close()
bad=[n for n,c in R if not c]; print('TOTAL',len(R),'PASS',len(R)-len(bad),'FAIL',len(bad)); sys.exit(1 if bad else 0)
